import {portraitArtwork} from './ui-kit.js';
import {depthDevelopment,depthPeople,depthSeason,depthRetirement} from './career-depth-ui.js';
import {competitionOutlook} from './career-tournaments.js';
import {overall,FOCUSES,POSITIONS} from './player-career-core.js';
import {IDENTITIES,PRIORITIES,SKILLS,selectionReport,currentCircuit,loanDestinations} from './career-chapters.js';
import {worldClub,table} from './career-world.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=id=>worldClub(id)?.name||'Earlier club';
const btn=(label,action,value='',disabled=false)=>`<button class="btn ${action==='advance'?'primary':'secondary'}" data-player-career="${action}" data-value="${esc(value)}" ${disabled?'disabled':''}>${esc(label)}</button>`;
const select=(id,label,values,value,disabled=false)=>`<label for="${id}">${label}</label><select id="${id}" ${disabled?'disabled':''}>${Object.entries(values).map(([k,v])=>`<option value="${k}" ${k===value?'selected':''}>${v}</option>`).join('')}</select>`;
const stat=(label,value)=>`<div><span>${label}</span><b>${value}</b></div>`;
function portrait(c){return portraitArtwork({...c,color:worldClub(c.club).color});}
function plan(c){return `<section class="card chapter-card"><span class="eyebrow highlight">BUILD YOUR IDENTITY</span><h2>${IDENTITIES[c.identity].name}</h2><p>Base ability ${overall(c)} · ${c.outlook.profile} development curve. Outlook is an authored simulation, not a guaranteed destination.</p><div class="pc-attributes">${Object.entries(c.attributes).map(([k,v])=>`<div><span>${{attack:'Finishing & movement',control:'Creation & technique',defense:c.role==='GK'?'Goalkeeping':'Defending',stamina:'Conditioning'}[k]}</span><b>${v.toFixed(1)}</b><div class="pc-meter"><i style="width:${v}%"></i></div></div>`).join('')}</div><details><summary>Full skill report</summary><div class="chapter-skills">${Object.entries(c.skills).filter(([k])=>c.role==='GK'?['reflexes','handling','distribution','positioning','reach','stamina','pace','control'].includes(k):!['reflexes','handling','distribution','reach'].includes(k)).map(([k,v])=>`<span>${SKILLS[k]} <b>${v.toFixed(1)}</b></span>`).join('')}</div></details>${depthDevelopment(c)}${select('pc-focus','Development direction',FOCUSES,c.focus,!!c.yearJob||c.retired)}${select('pc-intensity','Workload',{light:'Protect recovery · slower training',normal:'Balanced workload',intense:'Push training · greater fatigue and injury risk'},c.intensity,!!c.yearJob||c.retired)}${select('pc-priority','My career priority',PRIORITIES,c.priority,!!c.yearJob||c.retired)}<fieldset class="career-options"><legend>Optional competitions · next year</legend><label><input id="pc-europe" type="checkbox" ${c.competitionOptions?.europe?'checked':''} ${c.yearJob||c.retired?'disabled':''}> Champions League career</label><label><input id="pc-world" type="checkbox" ${c.competitionOptions?.world?'checked':''} ${c.yearJob||c.retired?'disabled':''}> World Cup career</label><p>Club qualification and national-team selection still apply. Changes lock for the current year.</p></fieldset>${competitionOutlook(c).map(t=>`<p class="stat-foot">${esc(t)}</p>`).join('')}<p class="stat-foot">Appropriate minutes, coaching environment, health, age and your identity affect growth. Plans lock when the year starts.</p></section>`;}
function club(c){const report=selectionReport(c),circuit=currentCircuit(c),tier=circuit.tiers.findIndex(t=>t.includes(c.club)),rows=table(circuit,tier);return `<section class="card chapter-card"><span class="eyebrow highlight">EARN YOUR PLACE</span><h2>${esc(name(c.club))}</h2><div class="chapter-metrics">${stat('PROJECTED ROLE',report.role)}${stat('LEAGUE MINUTES',report.minutes.join('–'))}${stat('ROLE FIT',report.fit)}</div><p>${report.explanation} Minutes are a forecast across 38 league fixtures, not a promise.</p>${report.position?`<p>Club role need: <strong>${report.position.need}</strong> · your familiarity ${report.position.familiarity}%.</p>`:''}<h3>Your competition</h3>${report.competitors.map(p=>`<div class="chapter-rival"><span>${p.name}<small>Simulated squad member · ${p.role}</small></span><b>${p.rating}</b></div>`).join('')}${depthPeople(c)}<h3>Relationship overview</h3><div class="chapter-people">${Object.entries(c.people).map(([k,v])=>`<span>${{coach:'Coach rapport',agent:'Agent rapport',mentor:'Mentor connection',support:'Support circle'}[k]} <b>${Math.round(v)}%</b></span>`).join('')}</div><h3>${esc(circuit.country)} circuit · Tier ${tier+1}</h3><p class="stat-foot">Touchline fantasy structure: two tiers, 38 league rounds, a cup and three promotion/relegation places. Fictional clubs and simulated squad members fill this career world.</p><div class="eu-table-wrap"><table class="league-table"><thead><tr><th>#</th><th>Club</th><th>P</th><th>GD</th><th>Pts</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.id===c.club?'chapter-user':''}"><td>${i+1}</td><td>${esc(name(r.id))}${r.id===c.club?' · YOU':''}</td><td>${r.p}</td><td>${r.gf-r.ga}</td><td>${r.pts}</td></tr>`).join('')}</tbody></table></div></section>`;}
function contracts(c){const loans=!c.loan?loanDestinations(c):[];return `<section class="card chapter-card"><span class="eyebrow highlight">YOUR AGENT DESK</span><h2>Choose the environment.<br>Shape the player.</h2>${c.contractReview?`<p class="chapter-alert">${c.contractReview}</p>`:''}<div class="chapter-metrics">${stat('CONTRACT',(c.contract/38).toFixed(1)+' seasons')}${stat('WEEKLY CREDITS',c.wage.toLocaleString())}${stat('CAREER EARNINGS',c.earnings.toLocaleString())}</div>${btn('Renew at current club','renew','',!!c.yearJob||!!c.loan||c.contract>38||c.retired)}<p class="stat-foot">Fictional game credits. Renewals and permanent moves are made between years. A loan retains your parent contract.</p>${c.loan?`<div class="chapter-alert"><h3>On loan from ${esc(name(c.loan.parent))}</h3><p>Return and squad review at the end of this year. Parent wage and remaining contract are preserved.</p></div>`:''}${c.eventHistory.filter(e=>e.season===c.season&&e.title==='Negotiations ended').slice(-1).map(e=>`<p class="chapter-alert">${esc(e.text)}</p>`).join('')}<h3>Compare contract offers</h3>${btn('Review realistic offers','refresh-offers','',!!c.yearJob||c.retired)}<p class="stat-foot">Country, current league, scouting access, senior minutes and reputation shape interest. These are authored game assessments, not predictions of an actual club’s decisions.</p><p>Ordered for your priority: ${PRIORITIES[c.priority]}. A vacancy does not guarantee starts.</p><div class="chapter-offers">${c.offers.map(o=>`<article class="chapter-offer"><span class="eyebrow">${esc(worldClub(o.club).country)} · ${o.interest??50}% INTEREST</span><h3>${esc(name(o.club))}</h3><strong>${esc(o.role)}</strong><dl><div><dt>League minutes</dt><dd>${o.minutes?.join('–')||'Uncertain'}</dd></div><div><dt>Coaching environment</dt><dd>${o.coaching??'—'} / 100</dd></div><div><dt>Role fit</dt><dd>${o.fit??'Unassessed'}</dd></div><div><dt>Weekly credits</dt><dd>${o.wage.toLocaleString()}</dd></div><div><dt>Term</dt><dd>${o.weeks/38} seasons</dd></div></dl><p>${esc(o.reason||'Earlier agent recommendation.')}</p>${btn('Sign with '+name(o.club),'offer',o.club,!!c.yearJob||!!c.loan||c.retired)}${btn(o.negotiated?'Counteroffer resolved':'Ask for higher wages','negotiate',o.club,!!c.yearJob||!!c.loan||!!o.negotiated||c.retired)}</article>`).join('')||'<p>Complete a year for fresh offers. A suitable development loan may still be available below.</p>'}</div>${loans.length?`<h3>A route to more minutes</h3><p>Season-long development loans with a parent-club review.</p>${loans.map(l=>`<div class="chapter-rival"><span>${esc(name(l.id))}<small>${l.minutes.join('–')} projected league minutes</small></span>${btn('Arrange loan','loan',l.id,!!c.yearJob||c.retired)}</div>`).join('')}`:''}</section>`;}
function story(c,all=false){const seasons=all?[...c.seasons].reverse():c.seasons.slice(-1);return `<section class="card chapter-card"><span class="eyebrow highlight">${all?'THE CAREER ARCHIVE':'THE YEAR IN FOCUS'}</span><h2>${all?'Every chapter stays with you.':seasons.length?'Your season. The whole story.':'Your debut is ahead of you.'}</h2>${seasons.map(s=>`<article class="chapter-season"><span class="eyebrow">SEASON ${s.season} · AGE ${s.age}</span><h3>${esc(name(s.club))}</h3>${s.competition?`<p class="chapter-season-result">Tier ${s.competition.tier} · ${s.competition.rank}${s.competition.rank===1?'st':s.competition.rank===2?'nd':s.competition.rank===3?'rd':'th'} · ${s.competition.points} points ${s.competition.promoted?' · PROMOTED':s.competition.relegated?' · RELEGATED':''}</p><p>Cup winner: ${esc(name(s.competition.cupWinner))}</p>`:'<p class="stat-foot">Preserved earlier annual record · generic opposition model.</p>'}<div class="chapter-metrics">${stat('APPEARANCES',s.appearances)}${stat('MINUTES',s.minutes)}${stat(c.role==='GK'?'SAVES':c.role==='DEF'?'RECOVERIES':'GOALS',c.role==='GK'?s.saves:c.role==='DEF'?s.recoveries??0:s.goals)}${stat('ASSISTS',s.assists??0)}${stat('AVG RATING',s.average.toFixed(1))}${stat('DEVELOPMENT',(s.development?.overall>=0?'+':'')+(s.development?.overall??'—')+' OVR')}</div><p>${esc(s.story||'This completed year is preserved from your earlier career.')}</p><p>${s.missed??0} fixtures missed through injury · ${s.development?.minutesShare??'—'}% of available match minutes.</p>${s.stints?.map(st=>`<div class="chapter-rival"><span>${esc(name(st.club))}</span><small>${st.appearances} apps · ${st.minutes} min · ${st.goals} goals</small></div>`).join('')||''}${depthSeason(c,s)}${tournamentReview(c,s)}${matchLog(c,s)}${c.eventHistory.filter(e=>e.season===s.season).map(e=>`<div class="chapter-story-event"><strong>${esc(e.title)}</strong><p>${esc(e.text)}</p></div>`).join('')}</article>`).join('')}<h3>Honours</h3>${c.honours.map(h=>`<p>S${h.season} · ${h.title} · ${esc(name(h.club))}</p>`).join('')||'<p>Your first honour is still ahead.</p>'}${all?`<h3>Club journey</h3>${c.transfers.map(t=>`<div class="chapter-rival"><span>S${t.season} · ${esc(t.type||'move')}<small>${esc(name(t.from))} → ${esc(name(t.to))}</small></span></div>`).join('')||'<p>Your first club chapter.</p>'}`:''}</section>`;}
function tournamentReview(c,s){return (c.tournamentArchive||[]).filter(t=>t.season===s.season).map(t=>{const team=id=>t.teams.find(x=>x.id===id)?.name||name(id);return `<details class="chapter-matchlog"><summary>${esc(t.label)} · ${t.year}</summary><p>${esc(t.reason||'Your club qualified for the European field.')} Winner: ${esc(team(t.champion))}</p><p class="stat-foot">${esc(t.note)}</p><div class="eu-table-wrap"><table class="league-table"><thead><tr><th>Stage</th><th>Home</th><th>Score</th><th>Away</th></tr></thead><tbody>${t.results.map(r=>`<tr class="${r.home===t.user||r.away===t.user?'chapter-user':''}"><td>${esc(r.stage)}</td><td>${esc(team(r.home))}</td><td>${r.score.join('–')}${r.pens?' · pens '+r.pens.join('–'):''}</td><td>${esc(team(r.away))}</td></tr>`).join('')}</tbody></table></div></details>`;}).join('');}
function matchLog(c,s){const rows=[...c.history,...c.cupHistory,...(c.extraHistory||[])].filter(r=>r.season===s.season);return `<details class="chapter-matchlog"><summary>Explore ${rows.length} recorded fixtures</summary><div class="eu-table-wrap"><table class="league-table"><thead><tr><th>Round</th><th>Club / opponent</th><th>Score</th><th>Min</th><th>G</th><th>A</th><th>Rec</th><th>Rating</th></tr></thead><tbody>${rows.sort((a,b)=>a.week-b.week).map(r=>`<tr><td>${r.week}<small>${r.competition||'Earlier model'}</small></td><td>${esc(name(r.club))}<small>vs ${esc(r.opponentName||'Generic opposition')}</small></td><td>${r.score.join('–')}</td><td>${r.minutes}</td><td>${r.goals}</td><td>${r.assists||0}</td><td>${r.recoveries||0}</td><td>${r.minutes?r.rating.toFixed(1):'—'}</td></tr>`).join('')}</tbody></table></div><p class="stat-foot">Shared statistical fixture outcomes. Annual games have no recorded physical replay.</p></details>`;}
export function renderChapterPage(c,state,{busy,creating,creation,retirementConfirm=false}){
 const report=selectionReport(c),last=c.seasons.at(-1),tab=state.tab,body=tab==='development'?plan(c):tab==='contracts'?contracts(c):tab==='club'?club(c):tab==='legacy'?story(c,true):tab==='story'?story(c):`<section class="card chapter-card chapter-next"><span class="eyebrow highlight">YOUR NEXT CHAPTER</span><h2>${c.retired?'A career to remember.':c.pendingDecision?'A turning point awaits.':c.contractReview?'Choose your next contract.':c.loan?'Make this loan count.':'Your place is there to earn.'}</h2><p>${esc(c.contractReview||c.arrival||report.explanation)}</p><div class="chapter-metrics">${stat('YOUR ROLE',report.role)}${stat('PROJECTED MINUTES',report.minutes.join('–'))}${stat('READINESS',Math.round(c.energy)+'%')}</div>${last?`<div class="chapter-story-event"><span class="eyebrow">LAST CHAPTER</span><h3>${esc(last.story||'Your previous year is recorded.')}</h3><p>${last.appearances} appearances · ${last.minutes} minutes · ${last.goals} goals · ${last.assists??0} assists</p>${btn('Read the season story','tab','story')}</div>`:''}${btn('Compare my opportunities','tab','contracts')}${btn('See my competition','tab','club')}</section>${plan(c)}`;
 return `<section class="hero"><div><div class="season-label"><span></span>PLAYER CAREER · CHAPTERS</div><h1>${esc(c.name.toUpperCase())}.<br><em>MAKE IT YOUR STORY.</em></h1><p>${POSITIONS[c.role]} · ${esc(c.nation)} · age ${c.age} · ${esc(name(c.club))}</p></div><div class="hero-actions">${btn('Create another player','new','',state.profiles.length>=8||busy)}</div></section><div class="pc-profiles"><label for="pc-profile">Your players<select id="pc-profile" ${busy?'disabled':''}>${state.profiles.map(p=>`<option value="${p.id}" ${p.id===c.id?'selected':''}>${esc(p.name)} · S${p.season}</option>`).join('')}</select></label><span>${state.profiles.length} / 8 separate careers</span></div>${creating?creation():`<div class="chapter-banner">${portrait(c)}<div class="chapter-banner-copy"><span class="eyebrow">${IDENTITIES[c.identity].name.toUpperCase()}</span><div class="chapter-rating">${overall(c)}<small>BASE ABILITY</small></div><h2>${esc(c.name)}</h2><p>${esc(name(c.club))} · ${report.role}</p><div class="chapter-metrics">${stat('AGE',c.age)}${stat('APPEARANCES',c.totals.appearances)}${stat('REPUTATION',Math.round(c.reputation))}</div></div></div>${!c.depth&&!c.yearJob&&!c.retired&&c.week===0?`<section class="card chapter-card"><h3>More personal career stories are ready.</h3><p>Keep your completed history and adopt rivals, position development, role recognition and retirement choices from this season. A recovery copy is saved before upgrading.</p>${btn('Enable deeper career','deepen')}</section>`:''}<nav class="pc-tabs" aria-label="Player career categories">${[['overview','Career home'],['development','Development'],['contracts','Agent desk'],['club','My club'],['story','Season story'],['legacy','Career archive']].map(([id,label])=>`<button class="btn ${tab===id?'primary':'ghost'}" aria-current="${tab===id?'page':'false'}" data-player-career="tab" data-value="${id}">${label}</button>`).join('')}</nav>${busy?'<section class="card chapter-card" role="status"><span class="eyebrow highlight">YOUR YEAR IS UNFOLDING</span><h2>Another chapter in the making…</h2><p>Resolving the league, cup, selection and development. Your last saved chapter stays safe.</p></section>':`${c.pendingDecision?`<section class="card pc-decision"><span class="eyebrow highlight">ONE TURNING POINT</span><h2>${esc(c.pendingDecision.title)}</h2><p>${esc(c.pendingDecision.text)}</p><div class="chapter-offers">${c.pendingDecision.choices.map(o=>`<article><h3>${esc(o.label)}</h3><p>${esc(o.trade)}</p>${btn(o.label,'decision',o.id)}</article>`).join('')}</div></section>`:''}<div class="pc-layout"><div>${body}${tab==='legacy'?depthRetirement(c,retirementConfirm):''}</div><aside><section class="card chapter-card chapter-sticky"><span class="eyebrow highlight">${c.retired?'YOUR LEGACY':c.yearJob?'YEAR IN PROGRESS':'THE NEXT YEAR'}</span><h3>${c.retired?'The final chapter.':'Age '+c.age+' → '+(c.age+1)}</h3><p>${c.retired?'Your completed seasons remain in the career archive.':c.yearJob?'Continue the same year after resolving your decision.':'One year at a time. At most one mid-year interruption.'}</p>${c.retired?'':btn(c.yearJob?'Continue the year':'Advance one year','advance','',!!c.pendingDecision||(!c.yearJob&&c.contract<38))}${c.contract<38&&!c.yearJob&&!c.retired?btn('Resolve my contract','tab','contracts'):''}<p>${c.retired?'Retired from professional football':c.injury?'Recovery · '+c.injury+' matchweeks remaining':'Available for selection'}</p><p>${(c.contract/38).toFixed(1)} seasons on contract${c.loan?' · on loan':''}</p><small>Statistical annual simulation. Authored Touchline ratings and a fantasy competition structure. No fabricated 3D match footage.</small></section></aside></div>`}`}`;
}
